```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate
WHERE {
  VALUES ?film { dbr:Tap_Roots dbr:Thenum_Vayambum }

  # director (prefer dbp:director, fallback to dbo:director)
  ?film ?directorProp ?director .
  FILTER ( ?directorProp = dbp:director || ?directorProp = dbo:director )

  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }

  # director death date (any available property)
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
  OPTIONAL { ?director dbp:deathDate ?deathDate . }
}
LIMIT 100
